using System;using System.Collections.Generic;using System.Linq;using MultiFPS;using MultiFPS.UI;using MultiFPS.Gameplay.RiftCombat;using ROM.Progression;using UnityEngine;using UnityEngine.UI;
namespace ROM.UI.Gameplay {
// Local feedback queue. It neither grants progress nor invents successful server actions.
public sealed class RiftAlertQueue {
 public sealed class Entry{public string Key,Title,Body;public int Priority;public float Duration;}
 readonly List<Entry> pending=new List<Entry>();readonly Dictionary<string,float> recent=new Dictionary<string,float>();public Entry Current{get;private set;}public float Started{get;private set;}public int Pending=>pending.Count;
 public bool Enqueue(string key,string title,string body,int priority,float now,float duration=3){if(string.IsNullOrWhiteSpace(title)||recent.TryGetValue(key,out float last)&&now-last<3)return false;if(Current?.Key==key||pending.Any(e=>e.Key==key))return false;recent[key]=now;if(recent.Count>64)foreach(var old in recent.Where(p=>now-p.Value>10).Select(p=>p.Key).ToArray())recent.Remove(old);pending.Add(new Entry{Key=key,Title=title,Body=body??"",Priority=priority,Duration=Mathf.Clamp(duration,1,6)});if(pending.Count>10)pending.Remove(pending.OrderBy(e=>e.Priority).First());return true;}
 public void Tick(float now){if(Current!=null&&now-Started>=Current.Duration)Current=null;if(Current==null&&pending.Count>0){Current=pending.OrderByDescending(e=>e.Priority).First();pending.Remove(Current);Started=now;}}
 public float Alpha(float now)=>Current==null?0:Mathf.Min(Mathf.Clamp01((now-Started)/.25f),Mathf.Clamp01((Current.Duration-(now-Started))/.4f));
}
public sealed class RiftZoneEntryGate {public string Current{get;private set;}="";string candidate="";float since;public bool Observe(string zone,float now){if(string.IsNullOrEmpty(zone)||zone==Current){candidate="";return false;}if(candidate!=zone){candidate=zone;since=now;return false;}if(now-since<.6f)return false;Current=zone;candidate="";return true;}}
[DefaultExecutionOrder(1200)]public sealed class RiftCombatAlerts:MonoBehaviour {
 public readonly RiftAlertQueue Queue=new RiftAlertQueue();public readonly RiftZoneEntryGate Zone=new RiftZoneEntryGate();public int GroundRegionCount=>grounds.Count;public float VisibleAlpha=>group?group.alpha:0;
 readonly Dictionary<Collider,string> grounds=new Dictionary<Collider,string>();RiftGameplayHUD hud;RectTransform panel;CanvasGroup group;Text title,body;float next;int level=-1;float seenNotice=-1;CanvasGroup oldNotice;float oldNoticeAlpha;
 void Awake(){hud=GetComponent<RiftGameplayHUD>();var definitions=new Dictionary<string,string>{{"Isla principal - 230 x 300 metros","Refugio inicial"},{"Isla de las ruinas","Ruinas occidentales"},{"Isla del cristal","Bosque de cristal"},{"Isla del bosque antiguo","Bosque del norte"},{"Distrito urbano - ciudad destruida","Distrito urbano"},{"Isla de la Ciudad del Sol","Ciudad del Sol"},{"Santuario del Eclipse - isla de 440 metros","Santuario del Eclipse"}};foreach(var c in FindObjectsByType<MeshCollider>(FindObjectsSortMode.None))if(definitions.TryGetValue(c.name,out var label)&&c.gameObject.scene==gameObject.scene)grounds[c]=label;
  panel=new GameObject("Local gameplay alerts",typeof(RectTransform)).GetComponent<RectTransform>();panel.SetParent(hud.Design,false);panel.anchorMin=panel.anchorMax=panel.pivot=new Vector2(.5f,1);panel.anchoredPosition=new Vector2(0,-35);panel.sizeDelta=new Vector2(640,88);var surface=panel.gameObject.AddComponent<RiftMapSurface>();surface.Fill=new Color(.025f,.03f,.05f,.83f);surface.Border=new Color(.48f,.37f,.68f,.7f);surface.raycastTarget=false;group=panel.gameObject.AddComponent<CanvasGroup>();group.blocksRaycasts=group.interactable=false;group.alpha=0;title=Label("Alert title",26,new Vector2(0,-10),34);body=Label("Alert detail",15,new Vector2(0,-48),28);var journal=GetComponent<RiftJournalHUD>();if(journal&&journal.Notification){oldNotice=journal.Notification.GetComponentInParent<CanvasGroup>();if(!oldNotice||oldNotice.gameObject==gameObject){oldNotice=journal.Notification.transform.parent.gameObject.AddComponent<CanvasGroup>();}oldNoticeAlpha=oldNotice.alpha;oldNotice.alpha=0;}
 }
 Text Label(string name,int size,Vector2 pos,float height){var rect=new GameObject(name,typeof(RectTransform)).GetComponent<RectTransform>();rect.SetParent(panel,false);rect.anchorMin=rect.anchorMax=rect.pivot=new Vector2(.5f,1);rect.anchoredPosition=pos;rect.sizeDelta=new Vector2(600,height);var t=rect.gameObject.AddComponent<Text>();t.font=hud.Theme.BodyFont;t.fontSize=size;t.color=new Color(.95f,.93f,1);t.alignment=TextAnchor.MiddleCenter;t.raycastTarget=false;return t;}
 void OnEnable(){AbilityController.ActionNotice+=Rejected;}void OnDisable(){AbilityController.ActionNotice-=Rejected;if(oldNotice)oldNotice.alpha=oldNoticeAlpha;if(group)group.alpha=0;}
 void Rejected(string text)=>Queue.Enqueue("error:"+text,text,"",90,Time.unscaledTime,2.4f);
 public string ZoneAt(Vector3 position){var ray=new Ray(position+Vector3.up*150,Vector3.down);foreach(var p in grounds){if(!p.Key)continue;var bounds=p.Key.bounds;if(position.x<bounds.min.x||position.x>bounds.max.x||position.z<bounds.min.z||position.z>bounds.max.z)continue;if(p.Key.Raycast(ray,out _,400))return p.Value;}return "";}
 void LateUpdate(){var player=ClientFrontend.ClientPlayerInstance;var c=player?player.GetComponent<AbilityController>():null;var actor=c?c.Actor:null;if(!actor||ClientFrontend.Hub){group.alpha=0;return;}float now=Time.unscaledTime;if(now>=next){next=now+.2f;if(level>=1&&c.Level>level){var unlocked=Enumerable.Range(1,7).Where(i=>c.AbilityRequiredLevel(i)>level&&c.AbilityRequiredLevel(i)<=c.Level).Select(i=>c.Definition(i).DisplayName);Queue.Enqueue("level:"+c.Level,"Nivel "+c.Level,string.Join(" · ",unlocked),100,now,4);}level=c.Level;string zone=ZoneAt(actor.transform.position);if(Zone.Observe(zone,now))Queue.Enqueue("zone:"+Zone.Current,Zone.Current,"El Rift",40,now,3.5f);if(!string.IsNullOrEmpty(Zone.Current))hud.MapZone.text=Zone.Current;if(RiftJournalView.NoticeUntil!=seenNotice&&RiftJournalView.NoticeUntil>now){seenNotice=RiftJournalView.NoticeUntil;Queue.Enqueue("quest:"+RiftJournalView.Notice,RiftJournalView.Notice,"",60,now,4);}}
  var field=FindFirstObjectByType<RiftFieldUI>();if(ClientFrontend.Pause||field&&field.MapOpen){group.alpha=0;return;}Queue.Tick(now);group.alpha=Queue.Alpha(now);if(Queue.Current!=null){title.text=Queue.Current.Title;body.text=Queue.Current.Body;}bool compactError=Queue.Current!=null&&Queue.Current.Key.StartsWith("error:");panel.anchorMin=panel.anchorMax=panel.pivot=compactError?new Vector2(.5f,0):new Vector2(.5f,1);panel.anchoredPosition=compactError?new Vector2(0,270):new Vector2(0,-35);panel.sizeDelta=new Vector2(compactError?360:Mathf.Min(640,((RectTransform)hud.Design).rect.width-560),compactError?46:88);title.fontSize=compactError?18:26;title.rectTransform.anchoredPosition=new Vector2(0,compactError?-6:-10);body.gameObject.SetActive(!compactError);title.rectTransform.sizeDelta=new Vector2(panel.sizeDelta.x-32,34);body.rectTransform.sizeDelta=new Vector2(panel.sizeDelta.x-32,28);
 }
}
}
